def norm(s):
    s=re.sub(r'https://www\.moducbt\.com/[^\n]+','',s)
    s=re.sub(r'\d{2}\.\s*\d{1,2}\.\s*\d{1,2}\.[^\n]*','',s)
    s=re.sub(r'(?m)^\s*\d+/\d+\s*$','',s)
    s=re.sub(r'\b[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}\b','',s)
    s=re.sub(r'\s+',' ',s).strip()
    for a,b in [('것 은','것은'),('옳 은','옳은'),('설 명','설명'),('있 다','있다'),('으 로','으로'),('해 서는','해서는'),('바르 게','바르게'),('기재 한','기재한'),('수 신기','수신기'),('경 계구역','경계구역'),('적 절한','적절한'),('해 당','해당'),('아 닌','아닌')]:s=s.replace(a,b)
    return s

def para(s):
    for a,b in [('다음 중','아래 내용 중'),('다음은','아래는'),('다음 조건','제시된 조건'),
      ('옳지 않은 것은?','잘못 설명한 것은?'),('옳은 것은?','맞게 설명한 것은?'),
      ('가장 적절하지 않은 것은?','가장 부적절한 것은?'),('가장 적절한 것은?','가장 타당한 것은?'),
      ('바르게 짝지은 것은?','정확하게 연결한 것은?'),('바르게 나열한 것은?','맞는 순서로 정리한 것은?'),
      ('해당하지 않는 것은?','포함되지 않는 것은?'),('에 관한 설명','에 대한 설명'),
      ('소방안전관리자가','소방안전관리 담당자가'),('상시 근무인원','상시 근무하는 인원'),
      ('주차장','주차구역'),('사무실','업무용 사무공간'),('적정 여부','적합 여부'),
      ('확인하였다','점검하였다'),('기재한다','기록한다'),('판단한다','판정한다')]:s=s.replace(a,b)
    s=s.replace('설명으로 맞게 설명한 것은?','설명 중 옳은 것은?').replace('설명으로 잘못 설명한 것은?','설명 중 틀린 것은?')
    for a,b in [('다음','아래'),('모두 고른 것은?','빠짐없이 선택한 것은?'),('바르게 연결한 것은?','정확하게 대응시킨 것은?'),('옳게 짝지은 것은?','맞게 짝지은 것은?'),('가장 높은 등급은?','최상위 등급은?'),('최소 인원은?','최소 인원으로 맞는 것은?'),('장소가 아닌 것은?','장소에 포함되지 않는 것은?'),('경우가 아닌 것은?','경우에 해당하지 않는 것은?'),('포함되어야 하는 사항이 아닌 것은?','포함할 사항으로 부적절한 것은?')]:s=s.replace(a,b)
    for a,b in [('〈보기〉','〈제시문〉'),('<보기>','<제시문>'),('이에 해당하는 스위치는?','이 기능을 하는 스위치의 명칭은?'),('상한이 바르게 연결된 것은?','상한의 연결이 정확한 것은?'),('이때 옥상에 별도로 설치해야 하는','이 조건에서 옥상에 추가로 확보할'),('해서는 안 되는 행위로 볼 수 없는 것은?','금지행위에 해당한다고 보기 어려운 것은?')]:s=s.replace(a,b)
    return s

def Q(stem,correct,wrong,reason,calc=None):
    assert len(wrong)==3
    return {'stem':stem,'correct':correct,'wrong':wrong,'reason':reason,'calculation':calc}

