add(23,'습한 기계실에서 반복 경보가 발생했다. 화재가 아님을 현장에서 확인한 뒤 할 적절한 조치는?','습기·누수·오염과 감지기 적응성을 확인하고 원인 제거 후 복구','감지기 회로를 끊어 놓고 계속 운영','확인 없이 경종만 영구 정지','수신기를 철거하고 화재 확인을 생략','비화재보도 실제 화재 확인이 먼저. 원인 제거·기기 복구·수신기 복구·정상 감시 상태 확인이 필요')
add(24,'전기설비 보호에 사용하는 이산화탄소 약제의 특성으로 맞는 것은?','전기 비전도성과 잔류물이 적은 장점이 있으나 인체 노출 위험이 크다','사람이 있는 밀폐공간에도 아무 조치 없이 방출해도 된다','모든 A급 깊은 불씨에 재발화 위험이 없다','전기가 잘 통하므로 전기화재에 적응성이 없다','CO₂는 전기 비전도성과 잔류물이 적은 특성을 활용하지만 질식·고농도 노출 위험을 함께 관리')
add(25,'공기 온도가 짧은 시간에 급격히 올라갈 때 그 변화율을 이용해 동작하는 감지기는?','차동식 열감지기','정온식 열감지기','광전식 연기감지기','불꽃감지기','차동식은 온도 상승률, 정온식은 일정 온도 도달을 이용함')
add(26,'예비전원시험을 누르는 동안 전압이 22V였다. 이 기기의 제시된 정상범위는 19~29V이다. 이 결과만으로 확정할 수 있는 것은?','표시 전압은 제시 범위에 들지만 지속시간과 자동 절환은 별도 확인한다','법정 지속시간 시험까지 모두 합격했다','29V보다 낮으므로 반드시 단선이다','상용전원 고장 여부와 무관하게 모든 기능이 정상이다','전압 표시 확인과 용량·자동 절환 확인은 서로 다른 시험 항목')
add(27,'승인 절차대로 실제 방출을 차단하고 가스계 교차회로 두 회로를 시험했다. 판단으로 맞는 것은?','경보·기동 신호 확인과 실제 약제 방출 여부를 구분한다','두 회로를 동작시키면 차단 상태와 무관하게 반드시 약제가 방출된다','점검이므로 방출 안전조치는 필요 없다','방호구역에 사람이 있으면 냄새로 약제 방출을 확인한다','오방출 방지 상태에서 회로·경보·연동을 확인하며 신호 발생과 실제 방출을 동일시하지 않음')
add(28,'다른 조건이 정상이고 감시제어반은 연동이다. 동력제어반에서 주펌프는 수동, 충압펌프는 자동일 때 압력 저하에 따른 자동기동 판단은?','주펌프 자동기동은 차단되고 충압펌프 자동기동은 가능','두 펌프 모두 자동기동 가능','주펌프만 자동기동 가능','수동 기동 명령 정지는 전원 차단과 항상 동일','동력제어반 선택 상태를 펌프별로 확인. 수동 상태를 자동 상태로 읽지 않음')
add(29,'펌프 최대유량 시험에서 설비측 토출밸브를 닫고 시험배관을 사용한다. 유량 설정으로 맞는 것은?','정격토출량의 150%로 조절한다','유량을 0으로 유지한다','정격토출량의 65%로 조절한다','펌프를 정지한 채 압력만 읽는다','최대유량 운전은 정격토출량 150%. 65%는 그 점에서 확보할 정격압력 대비 최소 압력 비율')
add(30,'24V 계통 수신기의 예비전원시험에서 정상범위를 19~29V로 제시했다. 도통시험 전압 4~8V를 적용하자는 의견에 대한 판단은?','시험 목적과 제시 범위가 다르므로 적용할 수 없다','두 시험은 항상 같은 전압을 사용한다','숫자가 작을수록 무조건 정상이다','예비전원은 전압 측정 대상이 아니다','예비전원과 회로도통시험의 정상범위를 혼동하지 않음. 실제 기기는 해당 기기 범례 적용')
add(31,'기동용기에 부착된 솔레노이드의 작동시험을 계획했다. 안전핀 제거 등 작동 조작 전에 우선할 것은?','승인된 절차로 실제 약제 방출 경로를 차단·분리하고 그 상태를 확인한다','사람에게만 알리고 바로 작동시킨다','먼저 격발해 약제가 나오는지 확인한다','방출 후에 환기할 창만 확보한다','실제 방출 차단이 먼저. 안전핀 또는 전기 정지 하나만으로 모든 기동 경로가 차단된다고 일반화하지 않음')
add(32,'감시제어반을 수동으로 선택해 기동 명령을 냈으나 주펌프가 돌지 않는다. 먼저 함께 확인할 것은?','동력제어반의 전원·선택 위치와 실제 기동 회로','감지기의 종류만 변경','경종 정지 스위치의 색상만 확인','주펌프가 정지했으므로 체절시험 합격 처리','감시제어반 명령과 실제 동력 공급·선택 상태를 연결해 확인')
add(33,'도통시험의 정상범위를 4~8V로 제시했다. 선택한 3회로의 지시값이 0V이면 적절한 조치는?','단선·종단저항 접속 등 회로 상태를 확인한다','감시 60분·경보 10분 용량 합격으로 기록','감지기의 열 감지 성능까지 정상으로 기록','0V이므로 수원량만 보충한다','0V는 제시된 도통 정상범위 밖. 배선·종단저항을 확인하며 모든 원인을 단선 하나로 확정하지 않음')
add(34,'습식 스프링클러 시험밸브함의 시험 목적은?','헤드 1개 개방에 해당하는 흐름으로 유수검지·경보 등을 확인','모든 헤드의 감열체를 열로 파괴','가스계 약제를 방출','동력제어반의 회로도통 전압만 측정','시험용 방수구의 흐름으로 헤드 개방을 대신하며 감열체 자체를 파괴하는 시험과 다름')
add(35,'감지기회로를 송배선식으로 하고 종단저항을 말단에 두는 주된 목적은?','회로 끝까지 이어지는 감시 경로 확보','정전 시 물을 방수','연기 농도를 숫자로 표시','소화펌프의 토출량 증가','종단저항과 송배선식은 회로 단선 등 감시 경로의 상태 확인을 위한 것')
add(36,'직사형 관창과 피토게이지로 방수압력을 측정할 때 맞는 방법은?','초기 공기·이물질을 배출하고 노즐선단 D/2 부근에서 흐름을 마주 보게 측정','분무형 관창의 외곽 물방울만 측정','펌프 압력계 값을 노즐선단 압력으로 대신','노즐에서 멀리 떨어진 물줄기 끝에서 측정','안정된 봉상주수의 중심에서 피토관 입구가 물 흐름을 받아야 함. D는 노즐 구경')
add(37,'발신기 버튼이 눌린 원인을 그대로 둔 채 수신기 복구만 반복했다. 예상되는 문제는?','발신기 신호가 계속되어 정상 감시상태 복귀가 어려울 수 있다','발신기 원인도 자동으로 반드시 제거된다','감지기 감도가 자동으로 영구 조정된다','소화기 압력이 자동으로 높아진다','현장 감지기·발신기의 원인 제거와 복구 후 수신기를 복구해야 함')
add(38,'평상시 펌프 자동기동을 유지하려는 학습용 제어반 조합으로 맞는 것은?','감시제어반 연동·자동 / 동력제어반 자동','감시제어반 수동 / 동력제어반 정지','감시제어반 전원 차단 / 동력제어반 자동','감시제어반 수동 / 동력제어반 수동','시험 종료 후 자동·연동 상태로 복구. 수동 명령의 정지와 자동 선택의 차단을 구별')
add(39,'감지기를 차례로 시험할 때 원인 신호가 사라지면 수신기도 따라 복구되게 하는 시험용 기능은?','자동복구 기능','주경종 정지 기능','지구경종 정지 기능','예비전원 감시 기능','자동복구와 경종 정지·예비전원 감시는 목적이 다름. 시험 후 정상 감시 상태 복구')
add(40,'청각장애가 있는 재실자의 피난을 도울 때 가장 적절한 방법은?','몸짓·빛·짧은 글 등 시각 정보를 이용해 방향을 알린다','뒤에서 갑자기 끌어당긴다','음성 방송만 반복하고 다른 수단은 쓰지 않는다','표정이나 이동 방향을 보여 주지 않는다','장애 특성에 맞는 의사소통·보조 방법을 사용하고 본인 의사를 확인')
add(41,'피난계획의 경로 범위로 맞는 것은?','각 거실에서 옥외로 이르는 경로이며 옥상·피난안전구역도 포함','각 거실에서 복도 중간까지의 경로만','방재실 직원의 출퇴근 경로','장비 납품 차량의 물류 동선만','피난계획은 거실에서 안전한 옥외 등에 이르는 경로와 인원·피난약자 보조 등을 연결')
add(42,'상시 근무인원 18명인 2급 대상물의 Type Ⅲ 편성을 검토한다. 편성인원이 10명 이상일 때 기본 팀 구성은?','비상연락·초기소화·피난유도팀','공사감리·설계·하자보수팀','지휘팀 하나만 두고 다른 역할 생략','현장대응팀만 반드시 허용','Type Ⅲ에서 편성인원 10명 미만의 현장대응팀 구성과 10명 이상 팀 구분을 구별')
add(43,'범례가 양호 ○, 불량 ×, 해당 없음 /인 점검표이다. 소화전함 앞 적치물로 문이 열리지 않는 항목의 표기는?','×','○','/','미확인 여부와 무관하게 ○','사용을 방해하는 적치물은 불량. 해당 없음 또는 미확인과 구별하여 위치·현상·조치도 기록')
add(44,'안전한 현장에서 성인의 반응이 없고 정상 호흡도 없으며 비정상적인 헐떡임만 보인다. 일반인 구조자의 조치는?','119 신고·AED 요청과 가슴압박 시작','맥박을 장시간 찾은 뒤 결정','물을 마시게 하며 대기','회복 자세만 유지하고 관찰 종료','헐떡임을 정상 호흡으로 보지 않으며 가슴압박을 지연하지 않음')
add(45,'AED가 심장리듬을 분석하고 전기충격을 시행할 때 지켜야 할 것은?','두 단계 모두 환자에게 접촉하지 않는다','분석 중에는 계속 환자 몸을 흔든다','충격 순간에만 패드를 떼어 낸다','분석 중 맥박을 직접 만져 장비 판단을 대신한다','분석·충격 중 접촉 금지. 충격 후 또는 충격 불필요 안내 후 즉시 가슴압박 재개')
add(46,'구급대 도착 전 응급처치의 일반원칙으로 맞는 것은?','구조자의 안전을 확인하고 환자의 반응·호흡과 상태 변화를 지속 관찰','의식이 흐려도 음료를 먹인다','처치가 익숙하지 않으면 119 지시를 무시','작은 상처 처치가 끝날 때까지 호흡 확인을 미룬다','안전·생명 위협 상태 확인이 먼저. 음식·음료·약을 임의로 주지 않으며 119 지시에 따름')
add(47,'피부 전층이 손상되고 표면이 건조하며 통증이 적을 수 있는 화상의 판별로 맞는 것은?','3도 화상 의심, 통증이 적어도 중증 가능','1도 화상 확정, 통증이 없으므로 진료 불필요','물집이 없으면 모든 화상은 경증','근육·뼈 손상까지 포함해야만 3도','3도와 근육·뼈 등 심부 조직까지 침범하는 4도를 구별. 통증 정도만으로 중증도를 낮추지 않음')
add(48,'많은 출혈 후 창백하고 피부가 차고 축축하며 빠르게 호흡한다. 가장 적절한 판단과 처치는?','쇼크를 의심하고 직접 압박·119 신고·보온과 관찰','갈증이 나면 음료를 계속 제공','모든 환자의 다리를 반드시 높이 올림','출혈 부위를 문질러 피가 더 흐르게 함','출혈성 쇼크 단서에 유의. 직접 압박하고 불필요한 이동·음식·음료를 피하며 119 지시 적용')
add(49,'신입자에게 처음 소방교육을 한다. 개선이 필요한 계획은?','장비 실습 없이 여러 주제를 한 번의 강의로만 설명하고 이해 확인을 생략','대상자의 경험에 맞춰 설명','장비를 안전하게 직접 조작하는 시간 확보','교육 후 핵심 행동을 수행해 보게 함','대상자의 경험·이해에 맞춰 단계적으로 실시하고 실습·반복·피드백을 활용')
add(50,'피난하려는 문 손잡이가 뜨겁고 틈으로 연기가 나온다. 적절한 행동은?','무리하게 열지 말고 안전한 다른 경로 또는 대피공간을 판단하고 구조 요청','연기를 빼기 위해 문을 활짝 열어 둠','상용 승강기를 무조건 사용','귀중품을 챙기러 화재실에 재진입','뜨거운 문을 무리하게 열거나 연기로 가득한 통로에 진입하지 않으며 현장 조건에 맞춰 피난·대기·구조 요청')
F[111]=Q('에틸알코올(C₂H₅OH)의 증기비중은 약 얼마인가? 공기 평균 분자량은 29, 원자량은 C=12·H=1·O=16으로 본다.','약 1.59',['약 0.63','약 29','약 46'],'분자량은 2×12+6×1+16=46. 공기를 기준으로 46÷29≈1.59',{'operation':'divide','inputs':[46,29],'expected':46/29})
