def main():
    ap=argparse.ArgumentParser();ap.add_argument('--source',required=True);args=ap.parse_args()
    source=Path(args.source);raw=json.loads(source.read_text());rows=raw['mapping']
    assert len(rows)==500 and len({r['sourceQuestionId'] for r in rows})==500
    chapters={}
    for p in (ROOT/'src/content/chapters/fire-safety-manager-level2').rglob('*.md'):
        t=p.read_text();m=re.search(r'chapter_id: ["\']?(FSM2-\d+)',t)
        if m:chapters[m[1]]={'path':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'text':t}
    bank=[];reviews=[];occ=collections.Counter();fail=[]
    answer_positions=[i for i in range(4) for _ in range(125)]
    random.Random(20261019).shuffle(answer_positions)
    old_positions=[r['displayedAnswer']-1 for r in rows]
    for i in range(500):
        if answer_positions[i]==old_positions[i]:
            j=next(j for j in range(500) if j!=i and answer_positions[j]!=old_positions[i] and answer_positions[i]!=old_positions[j])
            answer_positions[i],answer_positions[j]=answer_positions[j],answer_positions[i]
    assert all(a!=b for a,b in zip(answer_positions,old_positions))
    visual=re.compile(r'그림|사진|평면도|체계도|흐름도|다음과 같은 상태')
    for index,r in enumerate(rows,1):
        c=r['primaryChapter'];k=occ[c];occ[c]+=1
        parsed=re.split(r'정[답탑]\s*및\s*해설',r['sourceText'],maxsplit=1)
        parts=re.split(r'(?m)^\s*([1-4])\s*\n',parsed[0]);flags=[]
        # Safety/numeric families are re-authored against the corrected chapters.
        q=family(r,k)
        method='chapter-grounded-case' if q else 'source-text-variant'
        if index in F:q=F[index];method='ocr-set-re-authored' if index<=50 else 'chapter-grounded-case'
        if q is None and len(parts)==9 and parts[1::2]==['1','2','3','4']:
            choices=[norm(s) for s in parts[2::2]];a=r['displayedAnswer']-1
            question=para(norm(parts[0]));reason=norm(parsed[1].split('근거:')[0]) if len(parsed)>1 else ''
            if index==266:question=question.replace('지상 15층','지상 14층')
            if c=='FSM2-046' and visual.search(r['stem']):question='P형 수신기 감지기회로의 배선·구성요소에 대한 설명 중 옳지 않은 것은?'
            reason=re.sub(r'[①②③④]|(?:선택지|보기)\s*[1-4](?:번)?','해당 보기',reason)
            reason=re.sub(r'(?<!\d)[1-4]\s*번(?: 보기| 선택지)?','해당 보기',reason)
            q=Q(question,para(choices[a]),[para(t) for j,t in enumerate(choices) if j!=a],para(reason))
            if visual.search(question):flags.append('source-visual-context-review')
            flags.append('independent-answer-and-current-basis-review')
        if q is None:fail.append(index);continue
        new_answer=answer_positions[index-1];choices=q['wrong'].copy();choices.insert(new_answer,q['correct'])
        # Keep answer identities attached to their text through permutations.
        qid=f'FSM2-CORE-{index:03d}'
        bank.append({'id':qid,'chapterId':c,'subjectId':r['officialSubject'],'tags':['핵심'],'question':q['stem'],'choices':choices,'answerIndex':new_answer,'explanation':q['reason']})
        if method=='source-text-variant':flags.append('wording-transformation-only-no-claim-of-new-numeric-case')
        reviews.append({'id':qid,'sourceQuestionId':r['sourceQuestionId'],'sourceSet':r['sourceSetLabel'],'sourceQuestionNumber':r['questionNumber'],'sourcePDFPage':r['questionStartPage'],'sourceDisplayedAnswer':r['displayedAnswer'],'sourceIsOfficialExam':False,'chapter':{k:v for k,v in chapters[c].items() if k!='text'},'method':method,'calculation':q.get('calculation'),'reviewStatus':'draft','publicationApproved':False,'remainingChecks':flags or ['full-editorial-and-answer-review'],'sourceQuestionSHA256':hashlib.sha256(r['sourceText'].encode()).hexdigest()})
    assert not fail,fail
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/'core500.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n')
